--
-- Name: certificates; Type: TABLE; Schema: publication; Owner: -
--

CREATE TABLE publication.certificates (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    domain character varying(40) NOT NULL,
    certificate_type text NOT NULL,
    reporting_year integer NOT NULL,
    title text NOT NULL,
    issuer text,
    registration_id text,
    authorization_no text,
    serial_no text,
    certificate_date date,
    received_date date,
    invoice_no text,
    manifest_doc_no text,
    quantity_value numeric(14,3),
    quantity_unit text,
    original_filename text NOT NULL,
    storage_key text NOT NULL,
    mime_type text NOT NULL,
    byte_size bigint NOT NULL,
    sha256 character(64) NOT NULL,
    status text DEFAULT 'DRAFT'::text NOT NULL,
    display_order integer DEFAULT 0 NOT NULL,
    notes text,
    created_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    published_at timestamp with time zone,
    archived_at timestamp with time zone,
    CONSTRAINT ck_certificates_ck_certificates_byte_size_positive CHECK ((byte_size > 0)),
    CONSTRAINT ck_certificates_ck_certificates_domain_format CHECK (((domain)::text ~ '^[a-z][a-z0-9_]{1,39}$'::text)),
    CONSTRAINT ck_certificates_ck_certificates_mime_allowed CHECK ((mime_type = ANY (ARRAY['image/jpeg'::text, 'image/png'::text, 'application/pdf'::text]))),
    CONSTRAINT ck_certificates_ck_certificates_quantity_non_negative CHECK (((quantity_value IS NULL) OR (quantity_value >= (0)::numeric))),
    CONSTRAINT ck_certificates_ck_certificates_reporting_year_range CHECK (((reporting_year >= 2000) AND (reporting_year <= 2100))),
    CONSTRAINT ck_certificates_ck_certificates_sha256_format CHECK ((sha256 ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT ck_certificates_ck_certificates_status_allowed CHECK ((status = ANY (ARRAY['DRAFT'::text, 'PUBLISHED'::text, 'ARCHIVED'::text]))),
    CONSTRAINT ck_certificates_ck_certificates_status_timestamps CHECK ((((status = 'DRAFT'::text) AND (published_at IS NULL) AND (archived_at IS NULL)) OR ((status = 'PUBLISHED'::text) AND (published_at IS NOT NULL) AND (archived_at IS NULL)) OR ((status = 'ARCHIVED'::text) AND (archived_at IS NOT NULL)))),
    CONSTRAINT ck_certificates_ck_certificates_title_required CHECK ((length(TRIM(BOTH FROM title)) > 0)),
    CONSTRAINT ck_certificates_ck_certificates_type_required CHECK ((length(TRIM(BOTH FROM certificate_type)) > 0))
);


