    CONSTRAINT ck_public_release_metadata_ck_public_release_metadata_r_d757 CHECK ((length(TRIM(BOTH FROM reason)) > 0)),
    CONSTRAINT ck_public_release_metadata_ck_public_release_metadata_t_1461 CHECK ((((classification)::text = 'official'::text) OR (public_visible = false)))
