    manager_editable boolean DEFAULT true NOT NULL,
    calculation_method text,
    publication_class sustainability.publication_class NOT NULL,
    factor_code character varying(80),
    display_order smallint NOT NULL,
    is_active boolean DEFAULT true NOT NULL,
    CONSTRAINT metric_definitions_check CHECK (((min_value IS NULL) OR (max_value IS NULL) OR (min_value <= max_value))),
