    CONSTRAINT metric_definitions_display_order_check CHECK ((display_order > 0))
);


--
-- Name: outreach_programmes; Type: TABLE; Schema: sustainability; Owner: -
--

CREATE TABLE sustainability.outreach_programmes (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    submission_id uuid NOT NULL,
    programme_name character varying(300) NOT NULL,
    programme_date date NOT NULL,
    theme character varying(80) NOT NULL,
    other_theme character varying(200),
    partner_organisation character varying(300),
    programme_location character varying(300),
    programme_description text,
    school_students integer,
    college_students integer,
    farmers_agriculture integer,
    industrial_experts integer,
    researchers_experts integer,
    government_participants integer,
    participant_total integer GENERATED ALWAYS AS ((((((COALESCE(school_students, 0) + COALESCE(college_students, 0)) + COALESCE(farmers_agriculture, 0)) + COALESCE(industrial_experts, 0)) + COALESCE(researchers_experts, 0)) + COALESCE(government_participants, 0))) STORED,
    male_participants integer,
    female_participants integer,
    other_not_disclosed_participants integer,
    saplings_planted integer,
    experts_involved integer,
    volunteers_engaged integer,
    volunteer_hours numeric(12,2),
    remarks text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    waste_collected_kg numeric(12,2),
    species_identified_count integer,
    species_details jsonb,
    species_verification_notes text,
    CONSTRAINT outreach_counts_nonnegative CHECK (((COALESCE(school_students, 0) >= 0) AND (COALESCE(college_students, 0) >= 0) AND (COALESCE(farmers_agriculture, 0) >= 0) AND (COALESCE(industrial_experts, 0) >= 0) AND (COALESCE(researchers_experts, 0) >= 0) AND (COALESCE(government_participants, 0) >= 0) AND (COALESCE(male_participants, 0) >= 0) AND (COALESCE(female_participants, 0) >= 0) AND (COALESCE(other_not_disclosed_participants, 0) >= 0) AND (COALESCE(saplings_planted, 0) >= 0) AND (COALESCE(experts_involved, 0) >= 0) AND (COALESCE(volunteers_engaged, 0) >= 0) AND (COALESCE(volunteer_hours, (0)::numeric) >= (0)::numeric))),
    CONSTRAINT outreach_gender_not_above_total CHECK ((((COALESCE(male_participants, 0) + COALESCE(female_participants, 0)) + COALESCE(other_not_disclosed_participants, 0)) <= participant_total)),
    CONSTRAINT outreach_internal_impact_nonnegative CHECK (((COALESCE(waste_collected_kg, (0)::numeric) >= (0)::numeric) AND (COALESCE(species_identified_count, 0) >= 0))),
    CONSTRAINT outreach_other_theme_required CHECK ((((theme)::text <> 'other'::text) OR ((other_theme IS NOT NULL) AND (length(btrim((other_theme)::text)) > 0)))),
    CONSTRAINT outreach_programme_name_required CHECK ((length(btrim((programme_name)::text)) > 0)),
    CONSTRAINT outreach_species_details_array CHECK (((species_details IS NULL) OR (jsonb_typeof(species_details) = 'array'::text))),
    CONSTRAINT outreach_theme_allowed CHECK (((theme)::text = ANY ((ARRAY['climate_smart_agriculture'::character varying, 'climate_change'::character varying, 'afforestation'::character varying, 'water_conservation'::character varying, 'waste_management'::character varying, 'biodiversity_conservation'::character varying, 'hwcc'::character varying, 'livelihood_development'::character varying, 'campus_sustainability'::character varying, 'other'::character varying])::text[])))
);


